// src/pages/Community.js

import { useState } from "react";
import { useNavigate } from "react-router-dom";

function Community() {
  const navigate = useNavigate();

  // ==================================================
  // 모임 생성 모달
  // ==================================================

  const [showModal, setShowModal] = useState(false);

  // ==================================================
  // 책 검색
  // ==================================================

  const [search, setSearch] = useState("");

  // ==================================================
  // 새 모임 정보
  // ==================================================

  const [newMeeting, setNewMeeting] = useState({
    meetingName: "",
    selectedBook: null,
    date: "",
    time: "",
    people: 4,
    mood: "badge1",
  });

  // ==================================================
  // 더미 책 데이터
  // ==================================================

  const books = [
    {
      title: "노르웨이의 숲",
      author: "무라카미 하루키",
    },
    {
      title: "데미안",
      author: "헤르만 헤세",
    },
    {
      title: "어린왕자",
      author: "생텍쥐페리",
    },
    {
      title: "1984",
      author: "조지 오웰",
    },
    {
      title: "해변의 카프카",
      author: "무라카미 하루키",
    },
  ];

  // ==================================================
  // 모임 데이터
  // ==================================================

  const [meetings, setMeetings] = useState([
    {
      id: 1,
      title: "상실과 성장에 대하여",
      book: "노르웨이의 숲",
      time: "오늘 19:00",
      members: "4 / 6명",
      status: "모임중",
      mood: "badge1",

      // 현재 프론트 테스트용
      // 실제 백엔드에서는 방 생성자가 host가 됨
      isHost: true,
    },

    {
      id: 2,
      title: "나를 찾아가는 과정",
      book: "데미안",
      time: "오늘 20:00",
      members: "3 / 5명",
      status: "모집중",
      mood: "badge2",

      isHost: false,
    },

    {
      id: 3,
      title: "어른이 된다는 것",
      book: "어린왕자",
      time: "내일 18:30",
      members: "2 / 4명",
      status: "모집중",
      mood: "badge3",

      isHost: false,
    },
  ]);

  // ==================================================
  // 책 검색 결과
  // ==================================================

  const filteredBooks =
    search.trim() === ""
      ? []
      : books.filter((book) =>
          book.title
            .toLowerCase()
            .includes(search.toLowerCase())
        );

  // ==================================================
  // 모임 생성
  // ==================================================

  const addMeeting = () => {
    if (!newMeeting.meetingName.trim()) {
      alert("모임 이름을 입력해주세요.");
      return;
    }

    if (!newMeeting.selectedBook) {
      alert("책을 선택해주세요.");
      return;
    }

    if (!newMeeting.date) {
      alert("날짜를 선택해주세요.");
      return;
    }

    if (!newMeeting.time) {
      alert("시간을 선택해주세요.");
      return;
    }

    const newRoom = {
      id: Date.now(),

      title: newMeeting.meetingName,

      book: newMeeting.selectedBook.title,

      time: `${newMeeting.date} ${newMeeting.time}`,

      members: `1 / ${newMeeting.people}명`,

      status: "모집중",

      mood: newMeeting.mood,

      // ================================================
      // 중요
      //
      // 지금은 모임을 만든 사람이 방장이라고 가정
      // ================================================

      isHost: true,
    };

    setMeetings((prev) => [
      ...prev,
      newRoom,
    ]);

    // 모달 닫기
    setShowModal(false);

    // 입력값 초기화
    setNewMeeting({
      meetingName: "",
      selectedBook: null,
      date: "",
      time: "",
      people: 4,
      mood: "badge1",
    });

    setSearch("");
  };

  // ==================================================
  // 모임 입장
  // ==================================================

  const enterMeeting = (meeting) => {
    navigate("/meeting", {
      state: {
        title: meeting.title,

        mood: meeting.mood,

        // ==============================================
        // 방장 여부 전달
        // ==============================================

        isHost: meeting.isHost === true,
      },
    });
  };

  return (
    <div className="page">

      {/* =================================================
          상단
      ================================================= */}

      <div className="top-bar">

        <div className="logo">
          READLY
        </div>

        <button
          className="add-meeting-btn"
          onClick={() =>
            setShowModal(true)
          }
        >
          + 모임 만들기
        </button>

      </div>


      {/* =================================================
          안내
      ================================================= */}

      <div className="community-banner">
        ⏰ 모임 시작 10분 전까지
        참여 가능해요
      </div>


      {/* =================================================
          모임 카드
      ================================================= */}

      {meetings.map((meeting) => (

        <div
          className="group-card"
          key={meeting.id}
        >

          {/* ============================================
              모임 상단
          ============================================ */}

          <div className="group-header">

            <div>

              <div className="group-title">
                {meeting.title}
              </div>

              <div className="meeting-book">
                📚 {meeting.book}
              </div>

              <div className="group-info">
                {meeting.time}
              </div>

            </div>


            {/* ==========================================
                상태 / 분위기
            ========================================== */}

            <div className="badge-wrap">

              <div
                className={
                  meeting.status ===
                  "모임중"
                    ? "badge"
                    : "start-badge"
                }
              >
                {meeting.status}
              </div>


              <div
                className={meeting.mood}
              >

                {meeting.mood ===
                  "badge1" &&
                  "깊게 토론해요"}

                {meeting.mood ===
                  "badge2" &&
                  "부담없이 참여해요"}

                {meeting.mood ===
                  "badge3" &&
                  "함께 이야기해요"}

              </div>

            </div>

          </div>


          {/* ============================================
              모임 하단
          ============================================ */}

          <div className="group-footer">

            <span>
              {meeting.members}
            </span>


            <button
              className="join-btn"
              onClick={() =>
                enterMeeting(meeting)
              }
            >
              참여하기
            </button>

          </div>

        </div>

      ))}


      {/* =================================================
          모임 생성 모달
      ================================================= */}

      {showModal && (

        <div className="meeting-modal">

          <div className="meeting-modal-box">

            {/* ==========================================
                제목
            ========================================== */}

            <div className="modal-title">
              독서모임 만들기
            </div>


            {/* ==========================================
                모임 이름
            ========================================== */}

            <input
              placeholder="모임 이름"
              value={
                newMeeting.meetingName
              }
              onChange={(e) =>
                setNewMeeting({
                  ...newMeeting,

                  meetingName:
                    e.target.value,
                })
              }
            />


            {/* ==========================================
                책 검색
            ========================================== */}

            <div className="book-search">

              <input
                placeholder="책 제목 검색"
                value={search}
                onChange={(e) =>
                  setSearch(
                    e.target.value
                  )
                }
              />

            </div>


            {/* ==========================================
                검색 결과
            ========================================== */}

            {filteredBooks.map(
              (book, index) => (

                <div
                  key={index}
                  className="search-item"
                  onClick={() => {

                    setNewMeeting({
                      ...newMeeting,

                      selectedBook:
                        book,
                    });

                    setSearch("");

                  }}
                >

                  <div className="search-cover">
                    📚
                  </div>


                  <div>

                    <div className="book-name">
                      {book.title}
                    </div>

                    <div className="book-author">
                      {book.author}
                    </div>

                  </div>

                </div>

              )
            )}


            {/* ==========================================
                선택한 책
            ========================================== */}

            {newMeeting.selectedBook && (

              <div className="book-result">

                <div className="book-cover">
                  📚
                </div>


                <div>

                  <div className="book-name">
                    {
                      newMeeting
                        .selectedBook
                        .title
                    }
                  </div>

                  <div className="book-author">
                    {
                      newMeeting
                        .selectedBook
                        .author
                    }
                  </div>

                </div>

              </div>

            )}


            {/* ==========================================
                날짜 / 시간
            ========================================== */}

            <div className="date-time-wrap">

              <input
                type="date"
                value={
                  newMeeting.date
                }
                onChange={(e) =>
                  setNewMeeting({
                    ...newMeeting,

                    date:
                      e.target.value,
                  })
                }
              />


              <input
                type="time"
                value={
                  newMeeting.time
                }
                onChange={(e) =>
                  setNewMeeting({
                    ...newMeeting,

                    time:
                      e.target.value,
                  })
                }
              />

            </div>


            {/* ==========================================
                인원수
            ========================================== */}

            <div className="people-box">

              <div className="people-label">
                최대 인원
              </div>


              <div className="people-control">

                <button
                  onClick={() =>
                    setNewMeeting({
                      ...newMeeting,

                      people:
                        newMeeting.people >
                        2
                          ? newMeeting.people -
                            1
                          : 2,
                    })
                  }
                >
                  −
                </button>


                <span>
                  {newMeeting.people}명
                </span>


                <button
                  onClick={() =>
                    setNewMeeting({
                      ...newMeeting,

                      people:
                        newMeeting.people +
                        1,
                    })
                  }
                >
                  +
                </button>

              </div>

            </div>


            {/* ==========================================
                토론 유형
            ========================================== */}

            <select
              value={
                newMeeting.mood
              }
              onChange={(e) =>
                setNewMeeting({
                  ...newMeeting,

                  mood:
                    e.target.value,
                })
              }
            >

              <option value="badge1">
                깊게 토론해요
              </option>

              <option value="badge2">
                부담없이 참여해요
              </option>

              <option value="badge3">
                함께 이야기해요
              </option>

            </select>


            {/* ==========================================
                버튼
            ========================================== */}

            <div className="modal-btn-wrap">

              <button
                className="cancel-btn"
                onClick={() => {
                  setShowModal(false);
                  setSearch("");
                }}
              >
                취소
              </button>


              <button
                className="create-btn"
                onClick={addMeeting}
              >
                만들기
              </button>

            </div>

          </div>

        </div>

      )}

    </div>
  );
}

export default Community;
